import { withTimeout } from "../services/session-realtime-utils";
import { getAccessToken } from "./credentials";
import { githubIntegration } from "./github";
import { jobberIntegration } from "./jobber";
import { linearIntegration } from "./linear";
import { todoistIntegration } from "./todoist";
import type { BriefingContext, IntegrationModule } from "./types";

export {
  getIntegrationSyncModule,
  hasIntegrationSyncModule,
  listIntegrationSyncModuleIds,
  requireIntegrationSyncModule,
} from "./sync/registry";
export type {
  IntegrationSyncAdapter,
  IntegrationSyncModule,
  RemoteEntityDescriptor,
  SyncAdapterContext,
} from "./sync/types";

// Register all integration modules here — add new ones to this array
const modules = [githubIntegration, jobberIntegration, linearIntegration, todoistIntegration];

export async function getIntegrationBriefingContexts(
  userId: string,
  options?: { orgId?: string | null },
): Promise<BriefingContext[]> {
  const results: BriefingContext[] = [];
  for await (const context of streamIntegrationBriefingContexts(userId, options)) {
    results.push(context);
  }
  return results;
}

// Integration fetches have no abort path, so a hung provider request would
// otherwise stall dashboard action generation indefinitely.
export const BRIEFING_CONTEXT_TIMEOUT_MS = 30_000;

export async function* streamBriefingContexts(
  candidates: readonly IntegrationModule[],
  getToken: (integrationId: string) => Promise<string | null>,
  timeoutMs: number = BRIEFING_CONTEXT_TIMEOUT_MS,
): AsyncGenerator<BriefingContext> {
  const pending = new Set(
    candidates
      .filter((module) => module.getBriefingContext)
      .map((module) =>
        withTimeout(
          (async () => {
            const token = await getToken(module.id);
            if (!token) return null;
            return module.getBriefingContext?.(token);
          })(),
          timeoutMs,
          `[integrations] ${module.id} briefing context`,
        ).catch((err): null => {
          // A slow or failing provider must be visible in logs, not just absent.
          console.warn(
            `[integrations] ${module.id} briefing context unavailable:`,
            err instanceof Error ? err.message : err,
          );
          return null;
        }),
      ),
  );

  while (pending.size > 0) {
    const settled = await Promise.race(
      [...pending].map(async (promise) => ({
        promise,
        context: await promise,
      })),
    );
    pending.delete(settled.promise);
    if (settled.context) yield settled.context;
  }
}

export async function* streamIntegrationBriefingContexts(
  userId: string,
  options?: { orgId?: string | null },
): AsyncGenerator<BriefingContext> {
  yield* streamBriefingContexts(modules, (integrationId) =>
    getAccessToken(userId, integrationId, { orgId: options?.orgId }),
  );
}

export interface BriefingContext {
  /** Section label for LLM prompt (e.g., "LINEAR ISSUES") */
  label: string;
  /** Formatted text to inject into the LLM prompt */
  context: string;
  /** Action types this integration supports (e.g., ["linear_issue"]) */
  actionTypes: string[];
  /** Extra LLM instructions for handling this integration's data */
  instructions?: string;
}

export interface IntegrationModule {
  /** Must match integration.id in DB (e.g., "linear") */
  id: string;
  /** Return briefing context, or null if nothing relevant */
  getBriefingContext?(accessToken: string): Promise<BriefingContext | null>;
  // Sync-capable integrations register separately in integrations/sync/registry.ts
}

/**
 * Client-safe list of integration keys that have Collections sync modules.
 *
 * Each key must match Postgres `integration.id` and `IntegrationSyncModule.integrationId`.
 * When adding a sync adapter, add the key here and register the module in `registry.ts`.
 */
export const INTEGRATION_SYNC_MODULE_KEYS = [
  "attio",
  "linear",
  "github",
  "jobber",
  "apollo",
  "calcom",
  "mercury",
  "notion",
  "slack",
  "todoist",
  "hubspot",
  "salesforce",
  "wave",
  "quickbooks",
  "xero",
  "printavo",
  "shopmonkey",
  "housecallpro",
  "sage",
] as const;

export type IntegrationSyncModuleKey = (typeof INTEGRATION_SYNC_MODULE_KEYS)[number];

/**
 * Dual-OAuth adapters that mint Collections tokens via the broker `static` connection
 * (`usesBrokerSyncAccessToken`). Keep in sync with adapter modules — registry.test asserts.
 */
export const INTEGRATION_SYNC_BROKER_STATIC_KEYS = [
  "attio",
  "hubspot",
  "jobber",
  "mercury",
  "notion",
  "quickbooks",
  "sage",
  "salesforce",
  "wave",
  "xero",
  "housecallpro",
] as const satisfies readonly IntegrationSyncModuleKey[];

export type IntegrationSyncBrokerStaticKey = (typeof INTEGRATION_SYNC_BROKER_STATIC_KEYS)[number];

export function isIntegrationSyncModuleKey(
  integrationKey: string,
): integrationKey is IntegrationSyncModuleKey {
  return (INTEGRATION_SYNC_MODULE_KEYS as readonly string[]).includes(integrationKey);
}

export function isIntegrationSyncBrokerStaticKey(
  integrationKey: string,
): integrationKey is IntegrationSyncBrokerStaticKey {
  return (INTEGRATION_SYNC_BROKER_STATIC_KEYS as readonly string[]).includes(integrationKey);
}

export function listIntegrationSyncModuleKeys(): readonly IntegrationSyncModuleKey[] {
  return INTEGRATION_SYNC_MODULE_KEYS;
}

import { apolloSyncModule } from "./apollo";
import { attioSyncModule } from "./attio";
import { calcomSyncModule } from "./calcom";
import { githubSyncModule } from "./github";
import { housecallProSyncModule } from "./housecallpro";
import { hubspotSyncModule } from "./hubspot";
import { jobberSyncModule } from "./jobber";
import { linearSyncModule } from "./linear";
import { mercurySyncModule } from "./mercury";
import {
  INTEGRATION_SYNC_MODULE_KEYS,
  type IntegrationSyncModuleKey,
  isIntegrationSyncModuleKey,
} from "./module-manifest";
import { notionSyncModule } from "./notion";
import { printavoSyncModule } from "./printavo";
import { quickbooksSyncModule } from "./quickbooks";
import { sageSyncModule } from "./sage";
import { salesforceSyncModule } from "./salesforce";
import { shopmonkeySyncModule } from "./shopmonkey";
import { slackSyncModule } from "./slack";
import { todoistSyncModule } from "./todoist";
import type { IntegrationSyncModule } from "./types";
import { waveSyncModule } from "./wave";
import { xeroSyncModule } from "./xero";

/** Register sync adapter modules here — one entry per manifest key. */
const syncModulesByKey: Record<IntegrationSyncModuleKey, IntegrationSyncModule> = {
  attio: attioSyncModule,
  linear: linearSyncModule,
  github: githubSyncModule,
  jobber: jobberSyncModule,
  apollo: apolloSyncModule,
  calcom: calcomSyncModule,
  mercury: mercurySyncModule,
  notion: notionSyncModule,
  slack: slackSyncModule,
  todoist: todoistSyncModule,
  hubspot: hubspotSyncModule,
  salesforce: salesforceSyncModule,
  wave: waveSyncModule,
  quickbooks: quickbooksSyncModule,
  xero: xeroSyncModule,
  printavo: printavoSyncModule,
  shopmonkey: shopmonkeySyncModule,
  housecallpro: housecallProSyncModule,
  sage: sageSyncModule,
};

function validateSyncModuleRegistry(): void {
  for (const key of INTEGRATION_SYNC_MODULE_KEYS) {
    const module = syncModulesByKey[key];
    if (!module) {
      throw new Error(`Missing sync module for key "${key}" — add it to registry.ts`);
    }
    if (module.integrationId !== key) {
      throw new Error(
        `Sync module integrationId "${module.integrationId}" must match manifest key "${key}"`,
      );
    }
  }

  const unlisted = Object.keys(syncModulesByKey).filter((key) => !isIntegrationSyncModuleKey(key));
  if (unlisted.length > 0) {
    throw new Error(
      `Sync modules registered but missing from module-manifest.ts: ${unlisted.join(", ")}`,
    );
  }
}

validateSyncModuleRegistry();

export {
  INTEGRATION_SYNC_MODULE_KEYS,
  type IntegrationSyncModuleKey,
  isIntegrationSyncModuleKey,
  listIntegrationSyncModuleKeys,
} from "./module-manifest";

/** All integration keys that registered a sync module in code. */
export function listIntegrationSyncModuleIds(): string[] {
  return [...INTEGRATION_SYNC_MODULE_KEYS];
}

export function hasIntegrationSyncModule(integrationKey: string): boolean {
  return isIntegrationSyncModuleKey(integrationKey);
}

export function getIntegrationSyncModule(integrationKey: string): IntegrationSyncModule | null {
  if (!isIntegrationSyncModuleKey(integrationKey)) return null;
  return syncModulesByKey[integrationKey];
}

export function requireIntegrationSyncModule(integrationKey: string): IntegrationSyncModule {
  const module = getIntegrationSyncModule(integrationKey);
  if (!module) {
    throw new Error(`Integration ${integrationKey} does not implement sync`);
  }
  return module;
}

