import type { RemoteEntityOutboundOperations } from "../../domain/collection-sync-operations";
import type {
  InboundTransport,
  IntegrationSyncError,
  IntegrationSyncInterruptReason,
  IntegrationSyncStopMode,
  RemoteEntityKind,
  RemoteRecordOperation,
} from "../../domain/integration-sync";
import type { IntegrationSyncSettingsUiDescriptor } from "./settings-ui";

export type { RemoteEntityOutboundOperations } from "../../domain/collection-sync-operations";

/** Runtime context passed to every sync adapter call. */
export interface SyncAdapterContext {
  userId: string;
  orgId: string;
  /** Stable integration key — matches Postgres `integration.id` (e.g. `"attio"`). Not a UUID. */
  integrationId: string;
  accessToken: string;
}

export interface RemoteEntityDescriptor {
  id: string;
  label: string;
  kind: RemoteEntityKind;
  /** Provider-specific row subtitle for sync settings (Attio singular noun + slug). */
  description?: string | null;
  /**
   * Outbound record operations for this object.
   * Omitted fields default to true (full CRUD).
   */
  operations?: Partial<RemoteEntityOutboundOperations>;
}

export interface RemoteColumnDescriptor {
  id: string;
  name: string;
  type: string;
  nullable: boolean;
  /** Builder cannot rename/retype/remove the mirrored field. */
  schemaLocked: boolean;
  /**
   * User/SQL cannot change the value after the row exists (app, outbound CDC, UPDATE trigger).
   * When true, set `insertWritable: true` only for create-required fields (e.g. PR head branch).
   */
  valueReadOnly?: boolean;
  /** When `valueReadOnly` is true, allow setting the field on insert/create only. */
  insertWritable?: boolean;
  /** Remote entity id for reference columns — resolved when target sync is enabled. */
  refRemoteEntityId?: string | null;
}

export interface RemoteRecord {
  externalId: string;
  values: Record<string, unknown>;
  externalUpdatedAt?: string | null;
  externalVersion?: string | null;
}

export interface PullRecordsResult {
  rows: RemoteRecord[];
  nextCursor: string | null;
  /**
   * Optional provider high-water mark after this page (e.g. Jobber updatedAt).
   * Only commit after the inbound run completes successfully — never on pull alone.
   */
  terminalWatermark?: string | null;
}

export interface PushRecordChangeResult {
  externalId?: string;
  externalUpdatedAt?: string | null;
  externalVersion?: string | null;
}

export interface InboundChangeEvent {
  entityId: string;
  operation: RemoteRecordOperation;
  externalId: string;
  values?: Record<string, unknown>;
  externalUpdatedAt?: string | null;
  externalVersion?: string | null;
}

/** Normalized Genesis inbox delivery — framework-owned transport, adapter parses only. */
export type WebhookDelivery = {
  headers: Record<string, string>;
  payload: Uint8Array;
  registrationId: string;
  receivedAt: Date;
};

export type SetupProviderWebhookInput = {
  publicUrl: string;
  registrationId: string;
  enabledEntities: RemoteEntityDescriptor[];
};

export type TeardownProviderWebhookInput = {
  publicUrl: string;
  registrationId: string;
};

export interface IntegrationSyncCapabilities {
  inboundTransport: InboundTransport;
  supportsOutbound: boolean;
  supportsLocalExtensions: boolean;
}

/** Smoke harness metadata — optional per adapter (`pnpm run smoke:collections-sync`). */
export type IntegrationSyncSmokeDescriptor = {
  /** Provider object id exercised by the default smoke path. */
  defaultEntityId: string;
  /** Adapter unit tests the smoke runner executes. */
  unitTestFiles?: string[];
  /** Env var holding a live REST token for optional smoke checks. */
  liveAccessTokenEnvVar?: string;
};

export type InboundPullFailure = {
  error: IntegrationSyncError;
  interruptReason: IntegrationSyncInterruptReason;
};

export type OAuthConnectEnrichment = {
  grantedScopes?: string[];
  displayName?: string | null;
};

/**
 * Provider-specific sync surface. Genesis owns OAuth connect/disconnect,
 * collection DDL, CDC, and settings UI — adapters implement remote semantics only.
 */
export interface IntegrationSyncAdapter {
  /** Stable integration key — must match Postgres `integration.id` and `module-manifest.ts`. */
  readonly integrationId: string;

  capabilities(
    ctx: SyncAdapterContext,
  ): IntegrationSyncCapabilities | Promise<IntegrationSyncCapabilities>;

  discoverEntities(ctx: SyncAdapterContext): Promise<RemoteEntityDescriptor[]>;

  discoverSchema(ctx: SyncAdapterContext, entityId: string): Promise<RemoteColumnDescriptor[]>;

  pullRecords(
    ctx: SyncAdapterContext,
    entityId: string,
    cursor: string | null,
  ): Promise<PullRecordsResult>;

  pushRecordChange(
    ctx: SyncAdapterContext,
    entityId: string,
    externalId: string | null,
    changes: Record<string, unknown>,
    operation: RemoteRecordOperation,
  ): Promise<PushRecordChangeResult>;

  /** Poll fallback interval in seconds; omit or return null/0 when poll is disabled. */
  getPollIntervalSeconds?(
    ctx: SyncAdapterContext,
    entityId: string,
  ): number | null | Promise<number | null>;

  /** Framework passes the Genesis public URL. Adapter calls the provider webhook API only. */
  setupProviderWebhook?(ctx: SyncAdapterContext, input: SetupProviderWebhookInput): Promise<void>;

  teardownProviderWebhook?(
    ctx: SyncAdapterContext,
    input: TeardownProviderWebhookInput,
  ): Promise<void>;

  parseWebhookDelivery?(
    ctx: SyncAdapterContext,
    delivery: WebhookDelivery,
  ): Promise<InboundChangeEvent[]>;

  /** Optional provider signature verification before parseWebhookDelivery. */
  verifyWebhookDelivery?(ctx: SyncAdapterContext, delivery: WebhookDelivery): Promise<void>;

  /** Optional; framework hashes payload when omitted. */
  computeWebhookDedupeKey?(
    ctx: SyncAdapterContext,
    delivery: WebhookDelivery,
    events: InboundChangeEvent[],
  ): string | null | Promise<string | null>;

  /**
   * Reconcile durable inbound streams (gRPC Pub/Sub, SSE, etc.).
   * Required when `capabilities.inboundTransport` is `"poll_and_stream"`.
   * Idempotent: start/update subscriptions for currently enabled entities;
   * stop when none remain. Deliver normalized events via `applyInboundStreamEvents`.
   */
  reconcileInboundStream?(ctx: SyncAdapterContext): Promise<void>;

  /**
   * Tear down all process-local stream consumers for this integration
   * (graceful shutdown, disconnect). Prefer no network when possible.
   */
  stopInboundStream?(): Promise<void>;

  /**
   * Called after an inbound pull run completes successfully (all pages applied,
   * run marked complete). Use for durable provider watermarks — never advance
   * them inside `pullRecords`, or a failed apply will poison the next full pull.
   */
  afterSuccessfulInboundPull?(
    ctx: SyncAdapterContext,
    entityId: string,
    result: {
      recordsApplied: number;
      terminalWatermark?: string | null;
    },
  ): Promise<void>;

  /**
   * User clicked Refresh / Sync now. Clear incremental high-water marks so the
   * next pull re-fetches all remote rows instead of only updates after a stamp.
   */
  beforeManualInboundPull?(ctx: SyncAdapterContext, entityId: string): Promise<void>;
}

/**
 * Optional lifecycle hooks — orchestrator invokes these around Genesis-owned work.
 */
export interface IntegrationSyncLifecycle {
  /**
   * When Collections sync needs a different access token than mission MCP/session connect
   * (common with DCR + broker REST — see `integrations/sync/AGENTS.md`).
   * Framework falls back to `getAccessToken` when this returns null/undefined.
   */
  resolveSyncAccessToken?(input: {
    userId: string;
    orgId: string;
    integrationId: string;
  }): Promise<string | null | undefined>;

  /** Provider setup immediately before Genesis creates the virtual collection. */
  onBeforeEnableEntity?(
    ctx: SyncAdapterContext,
    entity: RemoteEntityDescriptor,
    input: { collectionDisplayName: string },
  ): Promise<void>;

  /** Provider cleanup after Genesis finishes enable (webhook registration, etc.). */
  onEntityEnabled?(
    ctx: SyncAdapterContext,
    entity: RemoteEntityDescriptor,
    input: { collectionId: string; collectionDisplayName: string },
  ): Promise<void>;

  /** Provider cleanup when sync stops — mode is keep_data (paused) or delete_data. */
  onEntityDisabled?(
    ctx: SyncAdapterContext,
    entityId: string,
    input: { mode: IntegrationSyncStopMode; collectionId: string | null },
  ): Promise<void>;


