import type { ConnectionCredentialPurpose } from "../domain/connection-credential-purpose";
import { connectionCredentialsAllowedForPurpose } from "../domain/connection-credential-purpose";
import { logConnectionCredentialDelivery } from "../lib/capability-log";
import { db } from "../lib/db";
import { buildConnectionCapabilityRuntimeEnvironment } from "./connection-capability-runtime-environment";
import { buildGoogleIdentityRuntimeEnvironment } from "./google-identity-integration";
import type { IntegrationRuntimeLogger } from "./integration-broker-connected-state";
import { buildPrintavoRuntimeEnvironment } from "./printavo-api-key-integration";
import { materializeUserMcpServersEnv, mergeUserMcpServersIntoEnv } from "./user-mcp-servers";

/**
 * Build the flat environment map for connected integrations.
 *
 * This is the single point where every connected-account credential is
 * materialized: broker connection capabilities, the Google IdP token
 * (`buildGoogleIdentityRuntimeEnvironment`), and the Printavo first-party API
 * key (`buildPrintavoRuntimeEnvironment`). Both the session environment and the
 * shared per-user sandbox environment are built from it, so it is also where
 * the caller's purpose decides whether those credentials are materialized at
 * all. A purpose that does not need a connected account gets an empty map: no
 * credential keys and no `GENESIS_INTEGRATION_*` availability signals, so
 * nothing in the session advertises a connected account as usable.
 */
export async function buildIntegrationRuntimeEnvironment(
  userId: string,
  orgId: string,
  purpose: ConnectionCredentialPurpose,
  logger?: IntegrationRuntimeLogger,
): Promise<Record<string, string>> {
  if (!connectionCredentialsAllowedForPurpose(purpose)) {
    logConnectionCredentialDelivery({ userId, orgId, purpose, outcome: "withheld" });
    return {};
  }

  const [googleEnv, printavoEnv, brokerEnv] = await Promise.all([
    buildGoogleIdentityRuntimeEnvironment(userId, logger, { orgId: orgId }),
    buildPrintavoRuntimeEnvironment(userId, orgId),
    buildConnectionCapabilityRuntimeEnvironment(userId, orgId, logger),
  ]);

  const env = { ...brokerEnv };
  for (const key of [
    "GOOGLE_WORKSPACE_CLI_TOKEN",
    "GOOGLE_WORKSPACE_CLI_CREDENTIALS_B64",
    "GENESIS_INTEGRATION_GOOGLE",
    "GENESIS_INTEGRATION_GOOGLE_REASON",
    "PRINTAVO_EMAIL",
    "PRINTAVO_TOKEN",
    "PRINTAVO_GRAPHQL_URL",
    "GENESIS_INTEGRATION_PRINTAVO",
  ] as const) {
    delete env[key];
  }
  Object.assign(env, googleEnv, printavoEnv);

  // User-managed outbound MCP servers fill MCP_SERVERS gaps only (broker wins).
  try {
    const userServers = await materializeUserMcpServersEnv({ db, userId, orgId });
    const merged = mergeUserMcpServersIntoEnv(env.MCP_SERVERS, userServers);
    if (merged) env.MCP_SERVERS = merged;
  } catch (error) {
    logger?.warn?.("[session-env] user MCP servers materialization failed", {
      userId,
      orgId,
      error: error instanceof Error ? error.message : String(error),
    });
  }

  logConnectionCredentialDelivery({ userId, orgId, purpose, outcome: "delivered" });
  return env;
}

export type { IntegrationRuntimeLogger };

