export type ApiKeyIntegrationDefinition = {
  id: string;
  name: string;
  description: string;
  /** Env key delivered by connection-capability template. */
  envKey: string;
  /** Validate key before persist (optional). */
  validateUrl?: string;
  apiBaseUrl: string;
  authorizationHeader: (apiKey: string) => string;
};

export const API_KEY_INTEGRATIONS: readonly ApiKeyIntegrationDefinition[] = [
