    envKey: "CALLRAIL_API_KEY",
    apiBaseUrl: "https://api.callrail.com/v3",
    validateUrl: "https://api.callrail.com/v3/a.json",
    authorizationHeader: (apiKey) => `Token token="${apiKey}"`,
  },
] as const;

const byId = new Map(API_KEY_INTEGRATIONS.map((item) => [item.id, item]));

export function isApiKeyIntegrationId(integrationId: string): boolean {
  return isApiKeyIntegrationIdClient(integrationId) && byId.has(integrationId.trim().toLowerCase());
}

export function getApiKeyIntegration(
  integrationId: string,
): ApiKeyIntegrationDefinition | undefined {
  return byId.get(integrationId.trim().toLowerCase());
}

export function listApiKeyIntegrations(): readonly ApiKeyIntegrationDefinition[] {
  return API_KEY_INTEGRATIONS;
}

async function ensureIntegrationCatalogRow(def: ApiKeyIntegrationDefinition): Promise<void> {
  await db
    .insert(integration)
    .values({
      id: def.id,
      name: def.name,
      description: def.description,
      authType: "api_key",
      oauthConfig: null,
      mcpConfig: { type: "none" },
      enabled: true,
    })
    .onConflictDoUpdate({
      target: integration.id,
      set: {
        name: def.name,
        description: def.description,
        authType: "api_key",
        mcpConfig: { type: "none" },
        enabled: true,
      },
    });
}

export async function isApiKeyIntegrationConnected(input: {
  userId: string;
  orgId: string;
  integrationId: string;
}): Promise<boolean> {
  if (!isApiKeyIntegrationId(input.integrationId)) return false;
  const [row] = await db
    .select({ id: userIntegration.id })
    .from(userIntegration)
    .where(
      and(
        eq(userIntegration.orgId, input.orgId),
        eq(userIntegration.userId, input.userId),
        eq(userIntegration.integrationId, input.integrationId.trim().toLowerCase()),
        eq(userIntegration.status, "active"),
      ),
    )
    .limit(1);
  return Boolean(row);
}

export async function getApiKeyIntegrationAccessToken(input: {
  userId: string;
  orgId: string;
  integrationId: string;
}): Promise<string | null> {
  const { decrypt } = await import("../lib/crypto");
  const [row] = await db
    .select({ credentials: userIntegration.credentials })
    .from(userIntegration)
    .where(
      and(
        eq(userIntegration.orgId, input.orgId),
        eq(userIntegration.userId, input.userId),
        eq(userIntegration.integrationId, input.integrationId.trim().toLowerCase()),
        eq(userIntegration.status, "active"),
      ),
    )
    .limit(1);
  if (!row) return null;
  try {
    const credentials = JSON.parse(decrypt(row.credentials)) as Record<string, string>;
    const token = credentials.accessToken?.trim();
    return token || null;
  } catch {
    return null;
  }
}

async function validateApiKey(def: ApiKeyIntegrationDefinition, apiKey: string): Promise<void> {
  const url = def.validateUrl;
  if (!url) return;
  const response = await fetch(url, {
    method: "GET",
    headers: { Authorization: def.authorizationHeader(apiKey), Accept: "application/json" },
    signal: AbortSignal.timeout(15_000),
  });
  if (response.status === 401 || response.status === 403) {
    throw new Error(`That ${def.name} API key was rejected. Create a new key in ${def.name}.`);
  }
  if (!response.ok) {
    throw new Error(`Could not verify the API key (HTTP ${response.status}). Try again.`);
  }
}

