import { IntegrationSyncError } from "../../../domain/integration-sync";
import type { IntegrationSyncModule, SyncAdapterContext } from "../types";
import { CallRailSyncClient } from "./client";
import {
  CALLRAIL_CALLS_ENTITY_ID,
  CALLRAIL_ENTITY_DESCRIPTORS,
  CALLRAIL_POLL_INTERVAL_SECONDS,
} from "./constants";

function createClient(ctx: SyncAdapterContext): CallRailSyncClient {
  return new CallRailSyncClient({ accessToken: ctx.accessToken });
}

/** Read-only CallRail v3 sync. Calls, texts, and form submissions are polled. */
export const callrailSyncModule: IntegrationSyncModule = {
  integrationId: "callrail",
  declaredEntities: CALLRAIL_ENTITY_DESCRIPTORS.map((entity) => ({ ...entity })),
  smoke: {
    defaultEntityId: CALLRAIL_CALLS_ENTITY_ID,
    unitTestFiles: [
      "src/integrations/sync/callrail/client.test.ts",
      "src/integrations/sync/callrail/flow.test.ts",
    ],
    liveAccessTokenEnvVar: "GENESIS_CALLRAIL_SYNC_ACCESS_TOKEN",
  },
  connectGrantsSyncAccess: true,
  capabilities() {
    return { inboundTransport: "poll", supportsOutbound: false, supportsLocalExtensions: false };
  },
  async discoverEntities() {
    return CALLRAIL_ENTITY_DESCRIPTORS.map((entity) => ({ ...entity }));
  },
  async discoverSchema(ctx, entityId) {
    return createClient(ctx).columnsForEntity(entityId);
  },
  getPollIntervalSeconds() {
    return CALLRAIL_POLL_INTERVAL_SECONDS;
  },
  async pullRecords(ctx, entityId, cursor) {
    return createClient(ctx).pullRecords(entityId, cursor);
  },
  async pushRecordChange() {
    throw new IntegrationSyncError("not_supported", "CallRail collections are read-only");
  },
};

